Load the active sheet and read cached values for the three data tables. For each agent block and category, sum column C where column H matches the existing wildcard and column F falls within the year range from the date row. Write the resulting yearly totals into the numeric cells of J39:O52.

```python
import shutil
import openpyxl
import re
from datetime import datetime, timedelta, date

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

sheet_name = vals.active.title
if sheet_name not in wb.sheetnames:
    sheet_name = "Total (2)" if "Total (2)" in wb.sheetnames else wb.sheetnames[0]

ws = wb[sheet_name]
vws = vals[sheet_name]

EPOCH = datetime(1899, 12, 30)

def to_serial(v):
    if v is None:
        return None
    if isinstance(v, datetime):
        return (v - EPOCH).total_seconds() / 86400.0
    if isinstance(v, date):
        return (datetime(v.year, v.month, v.day) - EPOCH).total_seconds() / 86400.0
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        return float(v)
    if isinstance(v, str):
        s = v.strip()
        if not s:
            return None
        for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d", "%m/%d/%Y %H:%M:%S", "%m/%d/%Y", "%d/%m/%Y"):
            try:
                dt = datetime.strptime(s, fmt)
                return (dt - EPOCH).total_seconds() / 86400.0
            except ValueError:
                pass
        try:
            return float(s)
        except ValueError:
            return None
    return None

def wildcard_match(value, crit):
    if value is None or crit is None:
        return False
    s = str(value).strip()
    if not s:
        return False
    pattern = "^"
    for ch in crit:
        if ch == "*":
            pattern += ".*"
        elif ch == "?":
            pattern += "."
        else:
            pattern += re.escape(ch)
    pattern += "$"
    return re.match(pattern, s, re.IGNORECASE) is not None

def get_criteria(cell):
    f = cell.value
    if isinstance(f, str):
        quoted = re.findall(r'"([^"]*)"', f)
        for q in quoted:
            if "*" in q or "?" in q:
                return q
        if quoted:
            return quoted[0]
    return None

# Data ranges: rentals, sales, commercial-lease
ranges = [(8, 37), (41, 58), (62, 74)]

# Blocks: (first total row, date row)
blocks = [(40, 43), (45, 48), (50, 53)]
default_criteria = ["*PE*", "*GS*", "*CC*"]
year_cols = [11, 12, 13, 14, 15]  # K through O

# Pre-read data rows
data_by_range = []
for r1, r2 in ranges:
    rows = []
    for r in range(r1, r2 + 1):
        agent = vws.cell(row=r, column=8).value
        date_s = to_serial(vws.cell(row=r, column=6).value)
        c = vws.cell(row=r, column=3).value
        c_val = float(c) if isinstance(c, (int, float)) and not isinstance(c, bool) else None
        rows.append((agent, date_s, c_val))
    data_by_range.append(rows)

for bi, (start_row, date_row) in enumerate(blocks):
    crit = get_criteria(ws.cell(row=start_row, column=11)) or default_criteria[bi]
    starts = [to_serial(vws.cell(row=date_row, column=col).value) for col in year_cols]

    for ci, (r1, r2) in enumerate(ranges):
        row = start_row + ci
        data = data_by_range[ci]

        for col, start_s in zip(year_cols, starts):
            total = 0.0

            if start_s is not None:
                dt = EPOCH + timedelta(days=start_s)
                end_dt = datetime(dt.year + 1, 1, 1)
                end_s = (end_dt - EPOCH).total_seconds() / 86400.0

                for agent, date_s, c_val in data:
                    if c_val is None or date_s is None:
                        continue
                    if not wildcard_match(agent, crit):
                        continue
                    if date_s >= start_s and date_s < end_s:
                        total += c_val

            if total == int(total):
                total = int(total)

            ws.cell(row=row, column=col).value = total
            print(f"sheet={sheet_name} row={row} col={col} crit={crit} start={start_s} total={total}")

wb.save(OUT)
